def max_borders(grid: list[str]) -> int:
    max_run = 0
    for row in grid:
        run = 0
        for ch in row:
            if ch == '#':
                run += 1
                max_run = max(max_run, run)
            else:
                run = 0
    if grid:
        for col in range(len(grid[0])):
            run = 0
            for row in range(len(grid)):
                if grid[row][col] == '#':
                    run += 1
                    max_run = max(max_run, run)
                else:
                    run = 0
    return max_run
